-- MERGE (upsert): insert if new, update if existing
MERGE employees AS target
USING staging_employees AS source ON target.employee_id = source.employee_id
WHEN MATCHED THEN
  UPDATE SET name = source.name, salary = source.salary
WHEN NOT MATCHED BY TARGET THEN
  INSERT (employee_id, name, salary) VALUES (source.employee_id, source.name, source.salary)
WHEN NOT MATCHED BY SOURCE THEN
  DELETE;   -- remove employees no longer in staging

-- OUTPUT: capture inserted IDs
DECLARE @inserted TABLE (id INT, name VARCHAR(100));
INSERT INTO employees (name, salary)
OUTPUT INSERTED.id, INSERTED.name INTO @inserted
VALUES ('Alice', 90000);
SELECT * FROM @inserted;  -- see what was inserted

-- OUTPUT: audit trail with before/after
UPDATE employees SET salary = salary * 1.1
OUTPUT DELETED.salary AS old_salary, INSERTED.salary AS new_salary,
       INSERTED.id, GETDATE() AS changed_at
INTO salary_audit;

-- FOR JSON PATH: serialize to JSON
SELECT id, name, salary FROM employees FOR JSON PATH, ROOT('employees');
-- Output: {"employees":[{"id":1,"name":"Alice","salary":90000},...]}

-- JSON_VALUE: extract scalar from JSON column
SELECT JSON_VALUE(metadata, '$.department') AS dept FROM employees;

-- OPENJSON: parse JSON array into rows
SELECT * FROM OPENJSON('[{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]')
WITH (id INT '$.id', name VARCHAR(100) '$.name');

-- Safe dynamic SQL with sp_executesql
DECLARE @sql NVARCHAR(MAX), @dept NVARCHAR(50) = 'Engineering';
SET @sql = N'SELECT * FROM employees WHERE dept = @dept_param';
EXEC sp_executesql @sql, N'@dept_param NVARCHAR(50)', @dept_param = @dept;
